import { EntityManager, In } from 'typeorm';
import { Status } from '../users/types';
import { User } from '../users/user.entity';

/**
 * Email domain shared by every seed user. seedUsers deletes users with this domain
 * before reseeding, so other local accounts are never touched.
 */
const SEED_EMAIL_DOMAIN = 'c4cneu.com';

/**
 * A sample user. IDs are generated by the database on insert.
 */
interface SeedUser {
  firstName: string;
  lastName: string;
  email: string;
  status: Status;
}

/**
 * Builds a seed user with an email in the first.last@c4cneu.com format.
 */
function buildSeedUser(
  firstName: string,
  lastName: string,
  status: Status,
): SeedUser {
  return {
    firstName,
    lastName,
    email: `${firstName}.${lastName}@${SEED_EMAIL_DOMAIN}`.toLowerCase(),
    status,
  };
}

/**
 * Five users for each role that has an account.
 */
export const SEED_USERS: SeedUser[] = [
  buildSeedUser('Sita', 'Raman', Status.ADMIN),
  buildSeedUser('Marcus', 'Johnson', Status.ADMIN),
  buildSeedUser('Elena', 'Vasquez', Status.ADMIN),
  buildSeedUser('Kenji', 'Watanabe', Status.ADMIN),
  buildSeedUser('Sophia', 'Lee', Status.ADMIN),

  buildSeedUser('Liam', 'Brown', Status.COMMUNITY_STAFF),
  buildSeedUser('Mateo', 'Herrera', Status.COMMUNITY_STAFF),
  buildSeedUser('Grace', 'Nguyen', Status.COMMUNITY_STAFF),
  buildSeedUser('Emma', 'Moore', Status.COMMUNITY_STAFF),
  buildSeedUser('Jamal', 'Wright', Status.COMMUNITY_STAFF),

  buildSeedUser('Olivia', 'Martinez', Status.PATIENT),
  buildSeedUser('Mei', 'Chen', Status.PATIENT),
  buildSeedUser('Olivia', 'Mendoza', Status.PATIENT),
  buildSeedUser('John', 'Price', Status.PATIENT),
  buildSeedUser('Arno', 'Dorian', Status.PATIENT),
];

/**
 * Replaces the seeded users, matched by exact email. Every other user is left
 * untouched.
 *
 * IDs are generated by the database, so seeding never collides with other users.
 *
 * @returns The inserted users, with their generated IDs.
 */
export async function seedUsers(manager: EntityManager): Promise<User[]> {
  await manager.delete(User, {
    email: In(SEED_USERS.map((user) => user.email)),
  });

  const users = SEED_USERS.map((seed) => manager.create(User, seed));
  return manager.save(User, users);
}

/**
 * Manually created Cognito accounts used to test auth/role edge cases. The rest of the
 * seed data is also idempotent, but gets there by deleting (or truncating) and recreating,
 * which assigns fresh ids and discards any state accumulated since the last reseed. These
 * are inserted only if missing instead, so a tester's account keeps the same id and
 * whatever state it's accumulated across reseeds.
 *
 * missing_db_user@c4cneu.gmail.com is deliberately not listed here: its Cognito account has
 * no matching row in this table, which is what it's used to test (the "no user record for
 * this email" 403 path in ResourcesService.create/findMine).
 */
export const AUTH_TEST_USERS: SeedUser[] = [
  {
    firstName: 'Insufficient',
    lastName: 'Role',
    email: 'insufficient_role@c4cneu.gmail.com',
    status: Status.COMMUNITY_STAFF,
  },
  {
    firstName: 'Admin',
    lastName: 'User',
    email: 'admin@c4cneu.gmail.com',
    status: Status.ADMIN,
  },
];

/**
 * Inserts each AUTH_TEST_USERS entry that isn't already present, matched by exact email.
 * An existing row with one of these emails is left untouched.
 *
 * @returns The number of users actually inserted (0 if they were all already present).
 */
export async function seedAuthTestUsers(
  manager: EntityManager,
): Promise<number> {
  const existing = await manager.find(User, {
    where: { email: In(AUTH_TEST_USERS.map((user) => user.email)) },
  });
  const existingEmails = new Set(existing.map((user) => user.email));

  const missing = AUTH_TEST_USERS.filter(
    (user) => !existingEmails.has(user.email),
  );
  if (missing.length === 0) {
    return 0;
  }

  await manager.save(
    User,
    missing.map((seed) => manager.create(User, seed)),
  );
  return missing.length;
}
